:root {
  --bg: #070a12;
  /* Same stack as `.site-footer` — deep charcoal + soft top lift (not pure black) */
  --surface-footer: radial-gradient(900px 420px at 50% 0%, rgba(255, 255, 255, 0.04), transparent 62%), var(--bg);
  --bg-2: #0a1022;
  --card: rgba(255, 255, 255, 0.06);
  --card-2: rgba(255, 255, 255, 0.08);
  --text: rgba(255, 255, 255, 0.92);
  --muted: rgba(255, 255, 255, 0.68);
  --muted-2: rgba(255, 255, 255, 0.54);
  --line: rgba(255, 255, 255, 0.10);
  --blue: #0b63f6;
  --blue-2: #3a86ff;
  /* Warm accent for dark sections (e.g. process), pairs with light text */
  --warm: #ff9f1c;
  --warm-2: #ffc266;
  --warm-glow: rgba(255, 159, 64, 0.32);
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.55);
  --radius: 18px;
  --radius-sm: 12px;
  --container: 1120px;
  /* White band (about / work) — ties to brand blue in borders & links */
  --light-canvas: #ffffff;
  --light-ink: #101218;
  --light-ink-mid: #3d424d;
  --light-ink-soft: #6b7280;
  --light-line: #e1e4eb;
  --light-line-strong: #cfd4dc;
}

/* Light theme (landing page toggle) */
:root[data-theme="light"] {
  --bg: #f6f7fb;
  --surface-footer: var(--light-canvas);
  --bg-2: #eef1f7;
  --card: rgba(11, 22, 55, 0.06);
  --card-2: rgba(11, 22, 55, 0.08);
  --text: rgba(10, 12, 18, 0.92);
  --muted: rgba(10, 12, 18, 0.68);
  --muted-2: rgba(10, 12, 18, 0.54);
  --line: rgba(10, 12, 18, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

html {
  overflow-x: clip;
  max-width: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial,
    "Apple Color Emoji", "Segoe UI Emoji";
  color: var(--text);
  background: #050712;
  overflow-x: clip;
  max-width: 100%;
  width: 100%;
}

:root[data-theme="light"] body {
  background: #f6f7fb;
}

/* Lincoln + Papillion (not Omaha): page canvas matches `.site-footer` — one fluid `--surface-footer` field behind main */
body.page-lincoln:not(.page-omaha) {
  --lincoln-mid-canvas: radial-gradient(900px 380px at 50% 0%, rgba(255, 255, 255, 0.06) 0%, transparent 60%), var(--bg);
  background: var(--surface-footer);
  background-attachment: scroll;
  background-repeat: no-repeat;
}

:root[data-theme="light"] body.page-lincoln:not(.page-omaha) {
  --lincoln-mid-canvas: radial-gradient(900px 380px at 50% 0%, rgba(10, 12, 18, 0.04) 0%, transparent 60%),
    linear-gradient(180deg, #f6f7fa 0%, #eef1f6 100%);
  background: var(--surface-footer);
  background-attachment: scroll;
  background-repeat: no-repeat;
}

/* Schuyler + Fremont (light): page canvas matches mid-band gradient so sections read as one field */
:root[data-theme="light"] body.page-lincoln:is(.page-schuylar, .page-fremont) {
  --surface-footer: var(--lincoln-mid-canvas);
  background: var(--lincoln-mid-canvas);
  background-attachment: scroll;
  background-repeat: no-repeat;
}

/* Light theme: flatter, more “professional” hero (remove dark overlays / glows) */
:root[data-theme="light"] .glow {
  display: none;
}

:root[data-theme="light"] .hero__grid {
  opacity: 0.085;
  mask-image: none;
}

:root[data-theme="light"] .about-hero .hero__grid {
  opacity: 0.095;
}

:root[data-theme="light"] .hero__vignette {
  background: none;
}

:root[data-theme="light"] .hero__image {
  filter: saturate(1) contrast(1);
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.container {
  width: min(100% - 40px, var(--container));
  margin-inline: auto;
}

/* Header / Nav */
.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 200;
  pointer-events: none;
}

.px-topbar {
  pointer-events: auto;
  background: #e85d04;
  color: rgba(252, 251, 249, 0.95);
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.px-topbar__inner {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.45rem 0.85rem;
  min-height: 2.25rem;
  padding: 0.4rem 0;
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  line-height: 1.2;
  text-align: center;
}

.px-topbar__link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: inherit;
  text-decoration: none;
  white-space: nowrap;
}

.px-topbar__icon {
  display: block;
  flex: 0 0 auto;
  opacity: 0.92;
}

.px-topbar__link:hover,
.px-topbar__link:focus-visible {
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 2px;
  outline: none;
}

.px-topbar__text {
  white-space: nowrap;
  opacity: 0.9;
}

.px-topbar__sep {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.45;
  flex: 0 0 auto;
}

@media (max-width: 720px) {
  /* One compact row: phone · place (keep designer line, drop years + email) */
  .px-topbar__text--years,
  .px-topbar__sep--years,
  .px-topbar__link--email,
  .px-topbar__sep--email {
    display: none;
  }

  .px-topbar__inner {
    justify-content: center;
    align-items: center;
    flex-wrap: nowrap;
    gap: 0.45rem 0.55rem;
    min-height: 2.35rem;
    padding: 0.4rem 0;
    font-size: 0.72rem;
    letter-spacing: 0.01em;
  }

  .px-topbar__text--place {
    display: inline;
    white-space: nowrap;
    max-width: min(58vw, 14.5rem);
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .px-topbar__link {
    max-width: none;
    overflow: visible;
    text-overflow: unset;
    padding: 0;
    gap: 0.3rem;
  }

  .px-topbar__icon {
    width: 12px;
    height: 12px;
  }
}

.nav {
  pointer-events: auto;
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 16px 0;
}

.site-header.is-scrolled .nav__inner {
  padding: 12px 0;
}

.nav__inner::before {
  content: "";
  position: absolute;
  inset: 0;
  height: 72px;
  background: linear-gradient(180deg, rgba(5, 7, 18, 0.72), rgba(5, 7, 18, 0.0));
  pointer-events: none;
  z-index: -1;
}

:root[data-theme="light"] .nav__inner::before {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.86), rgba(255, 255, 255, 0.0));
}

/* Band-style pages: avoid a “white strip” above the hero in light theme */
:root[data-theme="light"] .page-contact .nav__inner::before,
:root[data-theme="light"] .page-webdesign .nav__inner::before,
:root[data-theme="light"] .page-branding .nav__inner::before,
:root[data-theme="light"] .page-blog .nav__inner::before {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.0), rgba(255, 255, 255, 0.0));
}

.site-header.is-scrolled .nav__inner::before {
  height: 76px;
  background: rgba(5, 7, 18, 0.88);
  border-bottom: 1px solid rgba(255, 255, 255, 0.10);
}

:root[data-theme="light"] .site-header.is-scrolled .nav__inner::before {
  background: rgba(255, 255, 255, 0.92);
  border-bottom: 1px solid rgba(10, 12, 18, 0.10);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 220px;
}

.brand__mark {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.35);
  display: grid;
  place-items: center;
  overflow: hidden;
}

:root[data-theme="light"] .brand__mark {
  background: rgba(255, 255, 255, 0.8);
  border-color: rgba(10, 12, 18, 0.10);
  box-shadow: 0 12px 34px rgba(10, 12, 18, 0.12);
}

.brand__text {
  display: grid;
  line-height: 1.05;
}

.brand__name {
  font-weight: 800;
  letter-spacing: -0.02em;
  font-size: 16px;
}

.brand__sub {
  font-weight: 600;
  color: var(--muted);
  font-size: 13px;
}

.nav__toggle {
  display: none;
  appearance: none;
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.92);
  border-radius: 0;
  width: 2.5rem;
  height: 2.5rem;
  padding: 0.35rem;
  margin: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  cursor: pointer;
  transition: color 0.2s ease;
}

.nav__toggle:hover,
.nav__toggle:focus-visible {
  color: #fff;
}

.nav__toggle:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

/* Three equal strokes — Heroicons / Rowem-style menu mark */
.nav__toggle-lines {
  width: 1.375rem;
  height: 1.5px;
  display: block;
  position: relative;
  background: currentColor;
  border-radius: 99px;
  transition: background 180ms ease;
}

.nav__toggle-lines::before,
.nav__toggle-lines::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 1.5px;
  border-radius: 99px;
  background: currentColor;
  transition: transform 180ms ease, top 180ms ease;
}

.nav__toggle-lines::before {
  top: -6.5px;
}

.nav__toggle-lines::after {
  top: 6.5px;
}

.nav__toggle[aria-expanded="true"] .nav__toggle-lines {
  background: transparent;
}

.nav__toggle[aria-expanded="true"] .nav__toggle-lines::before {
  top: 0;
  transform: rotate(45deg);
}

.nav__toggle[aria-expanded="true"] .nav__toggle-lines::after {
  top: 0;
  transform: rotate(-45deg);
}

:root[data-theme="light"] .nav__toggle {
  background: transparent;
  border: none;
  box-shadow: none;
  color: rgba(10, 12, 18, 0.88);
}

:root[data-theme="light"] .nav__toggle:hover,
:root[data-theme="light"] .nav__toggle:focus-visible {
  color: rgba(10, 12, 18, 1);
}

.nav__links {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 18px;
  flex: 1;
}

.nav__overlay {
  display: none;
}

.nav__menu {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.nav__menu > li {
  flex-shrink: 0;
}

.nav__link {
  font-weight: 600;
  font-size: 13px;
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.78);
  padding: 10px 10px;
  border-radius: 999px;
  white-space: nowrap;
  transition: background 160ms ease, color 160ms ease, transform 160ms ease;
}

/* Match <a> links: buttons reset font/line-height in UA styles and were misaligned */
.nav__link--toggle,
.nav__link--lang {
  font: inherit;
  display: inline-flex;
  align-items: center;
  appearance: none;
  border: 0;
  background: transparent;
  cursor: pointer;
  margin: 0;
  text-align: inherit;
  color: inherit;
}

/* Google Translate — load on demand; hide gadget/banner so layout stays intact */
.nav__translate-host,
#google_translate_element,
.goog-te-banner-frame,
.goog-te-balloon-frame,
body > .skiptranslate,
.goog-logo-link,
.goog-te-gadget {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  overflow: hidden !important;
}

/* GT injects top offset for its banner — keep page flush */
html.translated-ltr body,
html.translated-rtl body,
body.translated-ltr,
body.translated-rtl {
  top: 0 !important;
}

/* Keep GT font wrappers from painting yellow highlights */
.skiptranslate,
font {
  background-color: transparent !important;
  background: none !important;
  box-shadow: none !important;
}

.nav__service-wrap {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.nav__dropdown-toggle {
  padding-left: 6px;
  padding-right: 8px;
}

.nav__chev {
  display: inline-block;
  margin-left: 6px;
  opacity: 0.7;
  transform: translateY(-1px);
  font-size: 0; /* hide fallback glyph (can render as random letters) */
  width: 12px;
  height: 12px;
  vertical-align: middle;
}

.nav__chev::before {
  content: "";
  display: block;
  width: 6px;
  height: 6px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translate(2px, 2px) rotate(45deg);
}

.nav__link:hover {
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.94);
}

:root[data-theme="light"] .nav__link {
  color: rgba(10, 12, 18, 0.74);
}

:root[data-theme="light"] .nav__link:hover {
  background: rgba(10, 12, 18, 0.06);
  color: rgba(10, 12, 18, 0.92);
}

.nav__item {
  position: relative;
}

.nav__item--has-menu::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  height: 14px;
  /* Invisible hover bridge between trigger and dropdown */
}

.nav__dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  width: min(1020px, calc(100vw - 40px));
  max-width: calc(100vw - 24px);
  padding: 16px;
  border-radius: 18px;
  background: rgba(7, 10, 18, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.10);
  box-shadow: 0 28px 90px rgba(0, 0, 0, 0.62);
  backdrop-filter: blur(18px);
  transform: translateY(-8px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 160ms ease, transform 160ms ease;
}

.nav__dropdown-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  align-items: start;
}

.nav__dropdown-col {
  min-width: 0;
  padding: 8px 14px 10px;
}

.nav__dropdown-col + .nav__dropdown-col {
  border-left: 1px solid rgba(255, 255, 255, 0.08);
}

.nav__dropdown-title {
  margin: 0 0 12px;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.50);
}

.nav__dropdown-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 4px;
}

.nav__dropdown-link {
  display: block;
  padding: 10px 10px;
  border-radius: 12px;
  color: rgba(255, 255, 255, 0.80);
  font-weight: 750;
  font-size: 13px;
  border: 1px solid transparent;
  background: transparent;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease;
}

.nav__dropdown-link:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.10);
  color: rgba(255, 255, 255, 0.94);
}

.nav__dropdown-cta {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  padding: 12px 0 0;
  margin-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.nav__dropdown-all {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.90);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: -0.01em;
}

.nav__dropdown-all:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.18);
}

/* Desktop behavior: hover opens */
@media (min-width: 761px) {
  .nav__item--has-menu:hover .nav__dropdown,
  .nav__item--has-menu:focus-within .nav__dropdown,
  .nav__item--has-menu.is-open .nav__dropdown {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
  }

  .nav__item--has-menu:hover .nav__chev,
  .nav__item--has-menu:focus-within .nav__chev,
  .nav__item--has-menu.is-open .nav__chev {
    opacity: 1;
  }
}

.nav__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.theme-toggle {
  appearance: none;
  border: 1px solid rgba(255, 255, 255, 0.10);
  background: rgba(10, 16, 34, 0.35);
  color: var(--text);
  border-radius: 999px;
  padding: 10px 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 13px;
  letter-spacing: -0.01em;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(14px);
  cursor: pointer;
}

.theme-toggle:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.18);
}

.theme-toggle:focus-visible {
  outline: none;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45), 0 0 0 4px rgba(11, 99, 246, 0.22);
}

.theme-toggle__icon {
  display: inline-flex;
  align-items: center;
  line-height: 0;
  color: rgba(255, 255, 255, 0.86);
}

.theme-toggle__moon {
  display: none;
}

:root[data-theme="light"] .theme-toggle {
  background: rgba(255, 255, 255, 0.72);
  border-color: rgba(10, 12, 18, 0.10);
  box-shadow: 0 12px 34px rgba(10, 12, 18, 0.12);
}

:root[data-theme="light"] .theme-toggle:hover {
  background: rgba(255, 255, 255, 0.86);
  border-color: rgba(10, 12, 18, 0.14);
}

:root[data-theme="light"] .theme-toggle__icon {
  color: rgba(10, 12, 18, 0.80);
}

:root[data-theme="light"] .theme-toggle__sun {
  display: none;
}

:root[data-theme="light"] .theme-toggle__moon {
  display: inline;
}

.nav__phone,
.nav__email {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.86);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: -0.01em;
  backdrop-filter: blur(14px);
}

:root[data-theme="light"] .nav__phone,
:root[data-theme="light"] .nav__email {
  background: rgba(255, 255, 255, 0.72);
  border-color: rgba(10, 12, 18, 0.10);
  color: rgba(10, 12, 18, 0.86);
  backdrop-filter: blur(14px);
}

.nav__phone-icon {
  color: rgba(11, 99, 246, 0.95);
  display: inline-flex;
  align-items: center;
  line-height: 0;
}

.nav__phone-icon svg {
  display: block;
}

/* Email stays icon-only — address is too long for the header row */
.nav__email .nav__phone-text {
  display: none;
}

/* Header right-side controls: keep one-line, slimmer height (match theme toggle) */
.site-header .nav__right .nav__phone,
.site-header .nav__right .nav__email,
.site-header .nav__right .btn.btn--sm {
  padding: 8px 10px;
  font-size: 12.5px;
  min-height: 37px;
}

.site-header .nav__right .btn.btn--sm {
  padding-left: 12px;
  padding-right: 12px;
}

.site-header .nav__right .nav__phone,
.site-header .nav__right .nav__email {
  gap: 6px;
}

.site-header .nav__right .nav__phone-text,
.site-header .nav__right .btn {
  white-space: nowrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 999px;
  padding: 12px 16px;
  font-weight: 800;
  letter-spacing: -0.01em;
  font-size: 14px;
  border: 1px solid transparent;
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease,
    border-color 160ms ease;
  user-select: none;
  text-decoration: none;
}

.btn:hover,
.btn:focus,
.btn:focus-visible,
.btn:active,
.btn:visited {
  text-decoration: none;
}

.btn--sm {
  padding: 10px 14px;
  font-size: 13px;
}

/* Header CTAs can crowd around ~tablet/compact desktop widths */
@media (max-width: 1120px) {
  .nav__right {
    gap: 8px;
  }

  .nav__phone,
  .nav__email {
    gap: 6px;
    padding: 9px 10px;
    font-size: 12.5px;
  }

  .btn--sm {
    padding: 9px 12px;
    font-size: 12.5px;
  }
}

/* At tight widths, keep phone as icon-only to prevent collisions */
@media (max-width: 1024px) {
  .nav__phone-text {
    display: none;
  }

  .nav__phone,
  .nav__email {
    padding: 9px 10px;
  }
}

.btn--lg {
  padding: 14px 18px;
  font-size: 14px;
}

.btn--primary {
  color: white;
  background: linear-gradient(180deg, rgba(11, 99, 246, 1), rgba(9, 79, 207, 1));
  box-shadow: 0 18px 50px rgba(11, 99, 246, 0.26), 0 14px 40px rgba(0, 0, 0, 0.45);
  border-color: rgba(255, 255, 255, 0.10);
}

.btn--primary:hover {
  transform: translateY(-1px);
