}

/* FAQ */
.faq {
  max-width: 980px;
  margin: 0 auto;
}

.faq__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 14px;
  margin-top: 22px;
}

.faq details {
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.09);
  box-shadow: 0 16px 50px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  overflow: hidden;
  transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease,
    box-shadow 160ms ease;
}

.faq details:hover {
  border-color: rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.045);
}

.faq details:focus-within {
  border-color: rgba(58, 134, 255, 0.45);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.28), 0 0 0 3px rgba(58, 134, 255, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.faq summary {
  cursor: pointer;
  list-style: none;
  padding: 16px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: rgba(255, 255, 255, 0.92);
  line-height: 1.25;
}

.faq summary::after {
  content: "";
  width: 10px;
  height: 10px;
  flex: 0 0 10px;
  border-right: 2px solid rgba(255, 255, 255, 0.75);
  border-bottom: 2px solid rgba(255, 255, 255, 0.75);
  transform: rotate(45deg);
  transition: transform 160ms ease, border-color 160ms ease, opacity 160ms ease;
  opacity: 0.9;
}

.faq summary::-webkit-details-marker {
  display: none;
}

.faq details[open] summary {
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.05);
}

.faq details[open] summary::after {
  transform: rotate(-135deg);
  opacity: 1;
}

.faq__answer {
  padding: 14px 16px 16px;
  color: rgba(255, 255, 255, 0.70);
  line-height: 1.75;
  font-weight: 650;
  font-size: 14px;
}

.faq__answer a {
  color: rgba(160, 199, 255, 0.95);
  border-bottom: 1px solid rgba(160, 199, 255, 0.28);
}

.faq__answer a:hover {
  color: #ffffff;
  border-bottom-color: rgba(160, 199, 255, 0.5);
}

/* Service page: engagements (premium packages) */
.engagements {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px 16px;
}

.engagement {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid rgba(255, 255, 255, 0.10);
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 0 22px 80px rgba(0, 0, 0, 0.45);
  box-shadow: 0 22px 80px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  padding: 18px 16px 16px;
  overflow: hidden;
}

.engagement::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  /* Remove top sheen that reads as a hard horizontal band */
  background: none;
  pointer-events: none;
}

.engagement > * {
  position: relative;
  z-index: 1;
}

.engagement__badge {
  display: inline-flex;
