  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 90, 0, 0.55) 32%,
    rgba(255, 176, 0, 0.9) 50%,
    rgba(255, 31, 31, 0.55) 68%,
    transparent 100%
  );
}

/* Blog post page: one fluid `--surface-footer` canvas (article + final CTA; footer unchanged) */
body.page-blog-post {
