/* Scroll performance — fixed backgrounds removed above; these reduce work during active scroll */
body.is-scrolling .hero__ticker-track,
body.is-scrolling .px-stack__track,
body.is-scrolling .px-clients__track,
body.is-scrolling .px-t-scroll__track {
  animation-play-state: paused !important;
}

body.is-scrolling .hero__video {
  visibility: hidden;
}

body.is-scrolling .hero__image--drone-fallback {
  visibility: visible;
}

@media (hover: none), (pointer: coarse) {
  .service-card,
  .trust,
  .hero__ticker-outer,
  .nav__dropdown,
  .work-tile {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }
}

/*
 * Dark theme scroll performance
 * Light mode is faster because it skips blur stacks, animated text gradients, masks, and filters.
 * Match that rendering path in dark without changing layout.
 */
:root:not([data-theme="light"]) * {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

:root:not([data-theme="light"]) .form-feedback-modal__backdrop {
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}

:root:not([data-theme="light"]) .btn--secondary {
  background: rgba(16, 22, 38, 0.92);
}

:root:not([data-theme="light"]) .accent:not(.accent--static) {
  animation: none !important;
  background-size: 100% 100% !important;
}

:root:not([data-theme="light"]) .page-home main > section:not(.hero) {
  content-visibility: auto;
  contain-intrinsic-size: auto 720px;
}

:root:not([data-theme="light"]) .hero__grid {
  mask-image: none !important;
  -webkit-mask-image: none !important;
}

:root:not([data-theme="light"]) .hero.is-offscreen .hero__bg {
  visibility: hidden;
}

:root:not([data-theme="light"]) :is(.process__glow, .panel__glow) {
  filter: none !important;
}

:root:not([data-theme="light"]) body.is-scrolling .glow,
:root:not([data-theme="light"]) body.is-scrolling .hero__grid,
:root:not([data-theme="light"]) body.is-scrolling .hero__vignette,
:root:not([data-theme="light"]) body.is-scrolling .process__glow,
:root:not([data-theme="light"]) body.is-scrolling [class*="__glow"] {
  visibility: hidden;
}

:root:not([data-theme="light"]) body.is-scrolling * {
  animation-play-state: paused !important;
}

:root:not([data-theme="light"]) body.is-scrolling :is(
  .service-card,
  .work-tile,
  .trust,
  .panel,
  .stat,
  .step,
  .faq__item,
  .g-review-card
) {
  box-shadow: none !important;
  transition: none !important;
}

/* Homepage reviews band: force flat edges (no zig-zag SVG dividers) */
body.page-home .section-divider--work-about,
body.page-home #about.light-band__segment::before,
body.page-home #about.light-band__segment::after {
  display: none !important;
  content: none !important;
  height: 0 !important;
  max-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  background-image: none !important;
  mask: none !important;
  mask-image: none !important;
  -webkit-mask-image: none !important;
  border: 0 !important;
  overflow: hidden !important;
}
